import threading
import time

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than 0")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be greater than 0")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.lock = threading.Lock()
        self.requests = {}

    def allow_request(self, client_id: str, current_time: float = None):
        if current_time is None:
            current_time = time.time()

        with self.lock:
            # Purge requests outside the window
            self.requests = {k: v for k, v in self.requests.items() if v >= current_time - self.window_seconds}

            # Check if the client has reached the limit
            if client_id in self.requests:
                if len(self.requests[client_id]) >= self.max_requests:
                    return False
            else:
                self.requests[client_id] = []

            # Register the current request
            self.requests[client_id].append(current_time)

        return True

