def find_first_occurrence(nums: list[int], target: int) -> int:
    if not nums:
        return -1

    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            # Check if this is the first occurrence
            if mid == 0 or nums[mid - 1] != target:
                return mid
            # If it's not the first occurrence, move left to find the first
            right = mid - 1
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    # Validación de precondiciones
    if not intervals:
        return []

    # Ordenar los intervalos por el inicio
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        # Si el intervalo actual comienza después del último intervalo en la lista combinada, agregarlo
        if interval[0] > merged[-1][1]:
            merged.append(interval)
        else:
            # Si el intervalo actual superpone con el último en la lista combinada, fusionarlos
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))

    return merged

